text:
{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Kestrel Logistics Corp."],
   "quote": "It is between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Kestrel Logistics Corp. (\"Kestrel\")."
  },
  "counterparty": {
   "value": "Kestrel Logistics Corp.",
   "quote": "Kestrel Logistics Corp. (\"Kestrel\")"
  },
  "effective_date": {
   "value": "2026-05-30",
   "quote": "made on 30 May 2026 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 12,
   "quote": "The Agreement runs for 1 year from the Effective Date."
  },
  "auto_renewal": {
   "value": true,
   "quote": "It renews automatically for further periods of one (1) year each."
  },
  "renewal_notice_days": {
   "value": 60,
   "quote": "The notice must be given at least 60 days before the end of the current term."
  },
  "governing_law": {
   "value": "New York",
   "quote": "The laws of the State of New York govern this Agreement."
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "The cap is the total fees paid or payable in the twelve (12) months before the event that gave rise to the claim."
  },
  "payment_terms_days": {
   "value": 90,
   "quote": "Northwind must pay all undisputed invoices within ninety (90) days of receiving them."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Samuel Okafor",
   "email": "samuel.okafor@kestrel.example",
   "title": "General Counsel",
   "party": "Kestrel Logistics Corp."
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "auto_renewal_evergreen",
   "severity": "medium",
   "message": "The agreement renews automatically each year unless written notice is given at least 60 days before term end. With a 30 May 2026 start, the notice deadline is about 31 March 2027, so a missed deadline locks Northwind in for another year.",
   "quote": "It renews automatically for further periods of one (1) year each."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "high",
   "message": "The agreement has no confidentiality obligations, so Northwind's information shared with Kestrel is not contractually protected.",
   "quote": "Apart from what this Agreement expressly says, neither party gives any other warranty."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The agreement has no termination clause, either for convenience or for breach. Northwind has no clear exit before the term ends other than non-renewal.",
   "quote": "The Agreement runs for 1 year from the Effective Date."
  },
  {
   "id": "mutual_liability_cap_limits_recovery",
   "severity": "medium",
   "message": "The cap applies to both parties 'in all circumstances' and has no carve-outs. It may also limit Kestrel's indemnity for third-party claims and Northwind's recovery for serious harms.",
   "quote": "This applies in all circumstances."
  },
  {
   "id": "indemnity_one_sided_but_undefined",
   "severity": "low",
   "message": "Kestrel's indemnity is broad and undefined, with no procedure for defense or control of claims. It may be subject to the liability cap.",
   "quote": "Kestrel will indemnify Northwind and hold it harmless from third-party claims arising from the services."
  },
  {
   "id": "payment_terms_long_net90",
   "severity": "low",
   "message": "Northwind has 90 days to pay undisputed invoices. That is favorable to Northwind's cash flow but may lead Kestrel to push back or raise prices.",
   "quote": "Northwind must pay all undisputed invoices within ninety (90) days of receiving them."
  },
  {
   "id": "dispute_resolution_no_forum",
   "severity": "low",
   "message": "The agreement has no forum, jurisdiction or arbitration clause. After 20 Business Days of executive talks, either party may pursue remedies anywhere.",
   "quote": "If the dispute is not resolved within twenty Business Days, either party may pursue the remedies available to it."
  },
  {
   "id": "fees_undefined_in_msa",
   "severity": "low",
   "message": "Fees are left entirely to Statements of Work, so the MSA sets no overall spend limit.",
   "quote": "The fees for the services are set out in each Statement of Work."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a one-year Master Services Agreement between Northwind Labs, Inc. and Kestrel Logistics Corp. effective 30 May 2026. It renews automatically each year unless notice is given 60 days before term end, caps liability at 12 months of fees, and sets 90-day payment terms under New York law. It has no confidentiality or termination provisions."
}
